def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    return float(v) if v is not None and math.isfinite(v) and v > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r ** 3
            weight += x
    return float(4.0 * math.pi * total / (3.0 * weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    nearest = [math.inf] * len(sites)
    for b in s.get('neighbors', ()):
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if d > 0 and occ[j] > 0 and d < nearest[i]:
            nearest[i] = d
    coordination = [0.0] * len(sites)
    for b in s.get('neighbors', ()):
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if d > 0 and occ[j] > 0 and d <= 1.5 * nearest[i]:
            coordination[i] += occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
    return float(sum(occ[i] * coordination[i] for i in range(len(sites))) / weight)

