def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x > 0 and z is not None and math.isfinite(z) and z >= 0:
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    props = s.get('element_properties', {})
    data = {}
    for e, x in s.get('composition', {}).items():
        p = props.get(e, {})
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if x > 0 and ion is not None and affinity is not None and math.isfinite(ion) and math.isfinite(affinity) and ion > affinity:
            data[e] = (x, 0.5 * (ion + affinity), max(0.5, ion - affinity))
    denominator = sum(t[0] / t[2] for t in data.values())
    weight = sum(t[0] for t in data.values())
    if denominator <= 0 or weight <= 0:
        return 0.0
    mu = sum(t[0] * t[1] / t[2] for t in data.values()) / denominator
    variance = sum(t[0] * ((mu - t[1]) / t[2]) ** 2 for t in data.values()) / weight
    return float(math.sqrt(max(0.0, variance)))

def feature(s):
    props = s.get('element_properties', {})
    data = {}
    for e, x in s.get('composition', {}).items():
        p = props.get(e, {})
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if x > 0 and ion is not None and affinity is not None and math.isfinite(ion) and math.isfinite(affinity) and ion > affinity:
            data[e] = (x, 0.5 * (ion + affinity), max(0.5, ion - affinity))
    denominator = sum(t[0] / t[2] for t in data.values())
    if denominator <= 0:
        return 0.0
    mu = sum(t[0] * t[1] / t[2] for t in data.values()) / denominator
    sites = s.get('sites', ())
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    charges = [(mu - data[t['element']][1]) / data[t['element']][2] if t['element'] in data else 0.0 for t in sites]
    value = 0.0
    for b in s.get('neighbors', ()):
        d = b['distance_A']
        if d > 0 and d < 6.0:
            i = b['i']
            j = b['j']
            taper = (1.0 - (d / 6.0) ** 2) ** 2
            value += occ[i] * occ[j] * charges[i] * charges[j] * taper / d
    return float(value / (2.0 * atoms))
